/** The deployment last rebuilt for (a number from the Worker's version id), in the tag store next to the fleet's signature. */
const DEPLOY_SEEN_KEY = 'carmacars/deploy-seen';
function deployNumber(version: string | null): number {
  if (!version) return 0;
  let h = 0;
  for (let i = 0; i < version.length; i++) h = (Math.imul(h, 31) + version.charCodeAt(i)) | 0;
  return Math.abs(h) || 1;
}

type Env = Record<string, unknown>;
const busyMeter = new BusyMeter();
/** the cached-only flag, read from the tag store at most every 15 s per isolate (a D1 read per request would cost more) */
let busySeen = { at: 0, until: 0 };
async function busyUntil(env: Env): Promise<number> {
  const now = Date.now();
  if (now - busySeen.at > 15_000) busySeen = { at: now, until: (await readNumber(env, BUSY_KEY).catch(() => 0)) ?? 0 };
  return busySeen.until;
}

/** r32: the crawler flags (search scope, crawler guard) read at most every 30 s per isolate: a crawler on a place page
 *  asked the tag store (D1) on every request */
const flagSeen = new Map<string, { at: number; v: boolean }>();
async function flag(env: Env, key: string): Promise<boolean> {
  const now = Date.now();
  const f = flagSeen.get(key);
  if (f && now - f.at < 30_000) return f.v;
  const v = (await readNumber(env, key).catch(() => null)) === 1;
  flagSeen.set(key, { at: now, v });
  return v;
}
/** 2402: a number of the tag store (the market mask, the oldest model year), read at most every 30 s per isolate */
const numberSeen = new Map<string, { at: number; v: number }>();
async function storedNumber(env: Env, key: string): Promise<number> {
  const now = Date.now();
  const f = numberSeen.get(key);
  if (f && now - f.at < 30_000) return f.v;
  const v = (await readNumber(env, key).catch(() => null)) ?? 0;
  numberSeen.set(key, { at: now, v });
  return v;
}

class NonceAdder {
  constructor(private readonly nonce: string) {}
  element(el: { setAttribute(name: string, value: string): void }) {
    el.setAttribute('nonce', this.nonce);
  }
}

interface PublicObject { body: ReadableStream; httpEtag: string; httpMetadata?: { contentType?: string } }
interface PublicBucket { get(key: string): Promise<PublicObject | null> }

// The public photo bucket (vehicle photos, site photos, logos) under /media when the site runs on
// the R2 bindings (STORAGE_PROVIDER=r2-binding, NEXT_PUBLIC_VEHICLE_PHOTOS_URL ending in /media).
async function media(request: Request, env: Env, path: string, ctx: { waitUntil(p: Promise<unknown>): void }): Promise<Response> {
  const bucket = env.R2_VEHICLE_PUBLIC as PublicBucket | undefined;
  // a path that is not valid percent-encoding is a 404, never an error
  let key = '';
  try { key = decodeURIComponent(path.slice('/media/'.length)); } catch { key = ''; }
  if (!bucket || !key || key.includes('..') || (request.method !== 'GET' && request.method !== 'HEAD')) return new Response('Not found', { status: 404 });
  const etag = request.headers.get('if-none-match');
  // 2026-10-30: the data centre's copy first (a car page's photos are asked for by every visitor and crawler): no R2
  // read; a HEAD or a conditional request goes to R2 as before
  const edge = request.method === 'GET' && !etag ? await mediaCache()?.match(request.url).catch(() => undefined) : undefined;
  if (edge) return edge;
  const o = await bucket.get(key);
  if (!o) return new Response('Not found', { status: 404, headers: { 'cache-control': 'public, max-age=60' } });
  const headers = new Headers({ 'content-type': o.httpMetadata?.contentType ?? 'application/octet-stream', etag: o.httpEtag,
    'cache-control': 'public, max-age=86400, stale-while-revalidate=604800', ...securityHeaders(),
    // a file opened directly (an SVG especially) can never run script on this origin
    'content-security-policy': "default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; sandbox" });
  if (etag && etag === o.httpEtag) return new Response(null, { status: 304, headers });
  const res = new Response(request.method === 'HEAD' ? null : o.body, { headers });
  const c = request.method === 'GET' ? mediaCache() : null;
  if (!c) return res;
  const [a, b] = res.body!.tee();
  ctx.waitUntil(c.put(request.url, new Response(b, { headers })).catch(() => undefined));
  return new Response(a, { headers });
}

/** Cloudflare's cache of this data centre (caches.default); null outside the Worker. Kept for the file's max-age (a day). */
function mediaCache(): { match(u: string): Promise<Response | undefined>; put(u: string, r: Response): Promise<void> } | null {
  const c = (globalThis as unknown as { caches?: { default?: unknown } }).caches?.default;
  return c ? (c as ReturnType<typeof mediaCache>) : null;
}

// The listing worker's token: the same HMAC as src/server/listing-worker.ts (LINK_SIGNING_KEY, a fixed label).
async function workerToken(secret: string): Promise<string> {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const mac = new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode('carmacars-listing-worker-v1')));
  return Array.from(mac, (b) => b.toString(16).padStart(2, '0')).join('');
}

// Live visitors (migration 0060): the site's beacon, answered here before the app is loaded, so a batch of page
// views costs well under a millisecond of the Worker's time and one call to the database. Bots are dropped; the city
// comes from Cloudflare; the network address only feeds a salted rate-limit key; the signed-in user's own token goes
// with the call (an expired one falls back to an anonymous call).
// 0103: the beacon never holds the browser. The database call runs under waitUntil; a batch waits for it at most
// 2 seconds (its answer can carry a staff invite to chat) and a heartbeat 1.5 seconds, then the Worker answers 204 and
// the call finishes in the background. The last batch of a page (pagehide, sendBeacon) is answered 204 at once, and
// its session is ended after its events are stored. A slow or failing database is a 204, never a 502.
async function track(request: Request, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }): Promise<Response | null> {
  const sbUrl = env.NEXT_PUBLIC_SUPABASE_URL, sbKey = env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
  if (typeof sbUrl !== 'string' || typeof sbKey !== 'string' || !sbUrl) return null;
  const headers = { 'content-type': 'application/json', 'cache-control': 'no-store', ...securityHeaders() };
  const reply = (o: unknown, status = 200) => new Response(JSON.stringify(o), { status, headers });
  const none = () => new Response(null, { status: 204, headers: { 'cache-control': 'no-store', ...securityHeaders() } });
  const origin = request.headers.get('origin');
  if (foreignOrigin(origin, new URL(request.url).host)) return reply({ ok: false }, 403);
  const ua = request.headers.get('user-agent');
  if (isBot(ua, env.TRACK_ALLOW_HEADLESS === '1')) return reply({ ok: true, bot: true });
  const text = await request.text();
  if (text.length > MAX_BEACON_BYTES) return reply({ ok: false }, 413);
  let raw: unknown;
  try { raw = JSON.parse(text); } catch { return reply({ ok: false }, 400); }
  const rpc = (fn: string, args: unknown, bearer: string) => fetch(`${sbUrl.replace(/\/$/, '')}/rest/v1/rpc/${fn}`, {
    method: 'POST', headers: { apikey: sbKey, authorization: `Bearer ${bearer}`, 'content-type': 'application/json' },
    body: JSON.stringify(args), signal: AbortSignal.timeout(BEACON_GIVE_UP_MS) });
  const background = <T>(p: Promise<T>) => { ctx.waitUntil(p.catch(() => undefined)); return p; };
  // the heartbeat of an open page: one UPDATE, anonymous (the session already says who it is)
  if (isBeat(raw)) {
    const beat = cleanBeat(raw);
    if (!beat) return reply({ ok: false }, 400);
    const p = background(rpc('track_beat', { p: beat }, sbKey).then(async (r) => (r.ok ? await r.text() : null)));
    if (beat.end) return none();
    const out = await within(p, BEAT_WAIT_MS);
    return out ? new Response(out, { status: 200, headers }) : none();
  }
  const b = cleanBeacon(raw, ua);
  if (!b) return reply({ ok: false }, 400);
  const { end, ...batch } = b;
  const cf = ((request as unknown as { cf?: Record<string, unknown> }).cf ?? {});
  // the Live map (0242): Cloudflare's approximate position of the visitor's network, rounded here to 0.01 degree (about 1 km)
  const geo = { city: cf.city ?? null, region: cf.regionCode ?? null, country: cf.country ?? null, lat: roundGeo(cf.latitude), lon: roundGeo(cf.longitude),
    ip_key: await ipKey(request.headers.get('cf-connecting-ip'), sbKey.slice(-24)) };
  const token = readSession(parseCookieHeader(request.headers.get('cookie')))?.session.access_token;
  const ingest = async () => {
    let r = await rpc('track_ingest', { p: batch, p_geo: geo }, token ?? sbKey);
    if (token && (r.status === 401 || r.status === 403)) r = await rpc('track_ingest', { p: batch, p_geo: geo }, sbKey);
    const t = r.ok ? await r.text() : null;
    // the page closed: its session ends once its last events are in
    if (end) await rpc('track_beat', { p: { sid: b.sid, vid: b.vid, end: '1' } }, sbKey).then((x) => x.text());
    return t;
  };
  const p = background(ingest());
  if (end) return none();
  const out = await within(p, BEACON_WAIT_MS);
  return out ? new Response(out, { status: 200, headers }) : none();
}

// Turo by email (migration 0063): Cloudflare Email Routing hands every message sent to trips@in.carmacars.ca (a
// subdomain, so the root domain's Google Workspace mail is untouched) to this handler. The raw message goes to the app's
// /api/inbound/turo with the jobs' token; the app reads it and stores only the parsed fields. A message too large is
// refused; if the app cannot take it (the database is down), the handler throws, so the sender (Gmail) tries again.
// r36 (2110): a message to another address of in.carmacars.ca (an inbox of Program settings auto_reply_email_inboxes, help@ by
// default) goes to /api/inbound/ask first: the FAQ's answer, when the site is sure of it, is sent back with message.reply
// (from the address it was sent to, inside Cloudflare); anything else stays as before (the Turo reader).
interface InboundEmail { from: string; to: string; raw: ReadableStream; rawSize: number; setReject(reason: string): void; reply?(m: unknown): Promise<void>;
  headers?: { get(name: string): string | null } }
const MAX_EMAIL_BYTES = 1_000_000;

/** One share of the warm-up (0102): the next pages of this deploy's list, within the budget; the progress kept. */
async function warmTick(env: Env, rows: ReadonlyArray<{ slug?: unknown }>, deployed: number, warmed: number, self: { fetch(r: Request): Promise<Response> }, base: string): Promise<number> {
  const paths = warmPaths(rows);
  const start = warmDone(warmed, deployed);
  if (start >= paths.length) return 0;
  const origin = base.replace(/\/$/, '');
  const done = await warmBatch(paths, start, async (path) => {
    const res = await self.fetch(new Request(`${origin}${path}`, { headers: { 'user-agent': 'CarmaCars warm-up (cron)', accept: 'text/html' } }));
    await res.arrayBuffer();
  });
  await writeNumber(env, WARM_KEY, warmValue(deployed, done));
  return done - start;
}

// 0106: the warm-up again after a bulk import (the catalog and places workflows call it after their rebuild): the
// progress of this deploy's warm-up goes back to the start, the first share runs now, the cron ticks do the rest. The
// pages it renders are kept as their fresh and last good copies (src/lib/edge/page-cache.ts).
async function warmUp(request: Request, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }): Promise<Response> {
  const json = (o: unknown, status = 200) => new Response(JSON.stringify(o), { status, headers: { 'content-type': 'application/json', 'cache-control': 'no-store', ...securityHeaders() } });
  const secret = typeof env.LINK_SIGNING_KEY === 'string' ? env.LINK_SIGNING_KEY : '';
  if (!secret || !sameSecret(request.headers.get('authorization') ?? '', `Bearer ${await workerToken(secret)}`)) return json({ ok: false }, 401);
  const self = env.WORKER_SELF_REFERENCE as { fetch(r: Request): Promise<Response> } | undefined;
  const deployed = deployNumber(deploymentOf(env));
  if (!self || deployed === 0 || !(env.NEXT_TAG_CACHE_KV || env.NEXT_TAG_CACHE_D1)) return json({ ok: false, reason: 'no warm-up here (no service binding, version or tag store)' }, 409);
  const rows = await fleetRows(env);
  if (!rows) return json({ ok: false, reason: 'the fleet could not be read' }, 503);
  await writeNumber(env, WARM_KEY, warmValue(deployed, 0));
  const base = typeof env.NEXT_PUBLIC_APP_URL === 'string' ? env.NEXT_PUBLIC_APP_URL : new URL(request.url).origin;
  ctx.waitUntil(warmTick(env, rows, deployed, warmValue(deployed, 0), self, base).catch(() => undefined));
  return json({ ok: true, pages: warmPaths(rows).length }, 202);
}

/** r32: runs one of the app's job routes in this invocation (the instant notifications, src/lib/edge/notify-kick.ts) */
function runJob(env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
  return async (path: string): Promise<void> => {
    const secret = typeof env.LINK_SIGNING_KEY === 'string' ? env.LINK_SIGNING_KEY : '';
    if (!secret) return;
    const base = (typeof env.NEXT_PUBLIC_APP_URL === 'string' ? env.NEXT_PUBLIC_APP_URL : 'https://carmacars.ca').replace(/\/$/, '');
    const r: Response = await handler.fetch(new Request(`${base}${path}`, { method: 'POST', headers: { authorization: `Bearer ${await workerToken(secret)}` } }), env, ctx);
    await r.text();
  };
}

const worker = {
  async email(message: InboundEmail, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }): Promise<void> {
    const secret = typeof env.LINK_SIGNING_KEY === 'string' ? env.LINK_SIGNING_KEY : '';
    if (!secret) { message.setReject('Not set up'); return; }
    if (message.rawSize > MAX_EMAIL_BYTES) { message.setReject('Message too large'); return; }
    const base = typeof env.NEXT_PUBLIC_APP_URL === 'string' ? env.NEXT_PUBLIC_APP_URL : 'https://carmacars.ca';
    const raw = await new Response(message.raw).text();
    const auth = `Bearer ${await workerToken(secret)}`;
    if (!/^trips@/i.test(message.to)) {
      const a: Response = await handler.fetch(new Request(`${base.replace(/\/$/, '')}/api/inbound/ask`, {
        method: 'POST', body: raw, headers: { authorization: auth, 'content-type': 'message/rfc822', 'x-envelope-from': message.from, 'x-envelope-to': message.to }
      }), env, ctx);
      if (a.status !== 404) {
        const j = (await a.json().catch(() => null)) as { reply?: { subject: string; text: string; in_reply_to: string | null } } | null;
        if (j?.reply && message.reply) {
          try {
            const { replyMime } = await import('./src/features/auto-reply/faq');
            const mod = 'cloudflare:' + 'email';
            const { EmailMessage } = (await import(/* webpackIgnore: true */ mod)) as { EmailMessage: new (from: string, to: string, raw: string) => unknown };
            const domain = message.to.split('@')[1] ?? 'in.carmacars.ca';
            await message.reply(new EmailMessage(message.to, message.from, replyMime({ from: message.to, to: message.from, subject: j.reply.subject, text: j.reply.text,
              inReplyTo: j.reply.in_reply_to, id: `${crypto.randomUUID()}@${domain}`, date: new Date() })));
          } catch (e) { console.warn(`inbound email: the automatic answer was not sent (${e instanceof Error ? e.message.slice(0, 120) : 'error'})`); }
        }
        return;
      }
    }
    const r: Response = await handler.fetch(new Request(`${base.replace(/\/$/, '')}/api/inbound/turo`, {
      method: 'POST', body: raw,
      headers: { authorization: auth, 'content-type': 'message/rfc822', 'x-envelope-from': message.from, 'x-envelope-to': message.to }
    }), env, ctx);
    if (r.status === 413) { message.setReject('Message too large'); return; }
    if (!r.ok) throw new Error(`inbound email: the app answered ${r.status}`);
  },

  // Cloudflare cron trigger (wrangler.jsonc triggers.crons, every minute since r32; the jobs below on every fifth): the listing pipeline's
  // sweep and, hourly, the statement emails, through the app's own protected routes so they run with the
  // app's code and bindings.
  async scheduled(event: { scheduledTime?: number }, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }): Promise<void> {
    const secret = typeof env.LINK_SIGNING_KEY === 'string' ? env.LINK_SIGNING_KEY : '';
    if (!secret) return;
    // r32: the cron runs every minute; the minutes between the five-minute ticks only send the notices due (one small
    // database call, the app loaded only when a push or a text is due: src/lib/edge/notify-kick.ts)
    const plan = tickPlan(Number(event?.scheduledTime ?? Date.now()));
    if (!plan.full) { ctx.waitUntil(kickNow(env, runJob(env, ctx)).catch(() => undefined)); return; }
    const base = typeof env.NEXT_PUBLIC_APP_URL === 'string' ? env.NEXT_PUBLIC_APP_URL : 'https://carmacars.ca';
    const auth = { authorization: `Bearer ${await workerToken(secret)}` };
    const run = (path: string) => ctx.waitUntil(handler.fetch(new Request(`${base.replace(/\/$/, '')}${path}`, { method: 'POST', headers: auth }), env, ctx)
      .then((r: Response) => r.text()).catch(() => undefined));
    // only when the database has work for them (src/lib/edge/cron-gate.ts, 0076): an idle tick then never loads the app
    const due = await jobsToRun(env);
    // 0324: the month's crawler guard (the database: projected CPU cost above crawler_guard_usd, on until the month ends):
    // the flag the fetch handler reads (bot-shield.ts keptToScope), written only when it changes
    if (due.checked) ctx.waitUntil((async () => {
      const want = due.cpu_guard ? 1 : 0;
      if ((await readNumber(env, CPU_GUARD_KEY)) !== want) await writeNumber(env, CPU_GUARD_KEY, want);
      // the search scope (Settings > Vehicle pages): 1 for Core, which keeps crawlers to the crawl scope here
      const core = due.search_core ? 1 : 0;
      if ((await readNumber(env, SEARCH_SCOPE_KEY)) !== core) await writeNumber(env, SEARCH_SCOPE_KEY, core);
      // 1860: cached-only serving by usage (the month's Worker requests or CPU time past Program settings usage_cached_pct)
      const cached = due.cached_only ? 1 : 0;
      if ((await readNumber(env, USAGE_CACHED_KEY)) !== cached) await writeNumber(env, USAGE_CACHED_KEY, cached);
      // 2350: whether any place region outside Canada is on (the market); while none is, the fetch handler answers a US or
      // Mexican place page 404 before the app loads
      const foreign = due.place_foreign ? 1 : 0;
      if ((await readNumber(env, PLACE_FOREIGN_KEY)) !== foreign) await writeNumber(env, PLACE_FOREIGN_KEY, foreign);
      // 2402: the regions that are on (stored plus one) and the oldest model year with vehicle pages, for the edge 404s
      if (due.place_market !== undefined && (await readNumber(env, PLACE_MARKET_KEY)) !== marketStored(due.place_market)) await writeNumber(env, PLACE_MARKET_KEY, marketStored(due.place_market));
      if (due.vpage_min_year !== undefined && (await readNumber(env, VPAGE_MIN_YEAR_KEY)) !== due.vpage_min_year) await writeNumber(env, VPAGE_MIN_YEAR_KEY, due.vpage_min_year);
    })().catch(() => undefined));
    if (due.listing) run('/api/jobs/listing');
    // the search copy (cars, landing pages, articles) and IndexNow (migration 0061)
    if (due.seo) run('/api/jobs/seo');
    // the phone line (migration 0085): booking texts that are due and the AI one-liners of calls
    if (due.phone) run('/api/jobs/phone');
    // the AI interviews of remote applicants (migration 0380): transcripts left, the AI's scores, removed audio
    if (due.interviews) run('/api/jobs/interviews');
    // phone and browser alerts (migration 0300): only with the VAPID keys, and only when an alert is due
    ctx.waitUntil(pushWaiting(env).then((w) => { if (w) run('/api/jobs/push'); }).catch(() => undefined));
    // the Google reviews sync of the review request program (migration 0138), every 6 hours while connected
    if (due.reviews) run('/api/jobs/reviews');
    // r37 (2303): interview calls waiting for their Google Calendar event and Meet link
    if (due.meet) run('/api/jobs/meet');
    // r42 (2640): the day's Search Console sync, once a day while connected
    if (due.gsc) run('/api/jobs/gsc');
    // the ads job (migration 0167): posted ads checked against the rates, the week's social drafts, Meta publishing when on
    if (due.ads) run('/api/jobs/ads');
    // 1202: the AI value estimate of cars with no Black Book value (the RentalCover cap), within the free Workers AI allowance
    if (due.car_values) run('/api/jobs/car-values');
    // a car put on or taken off the site in the database alone (0070's automatic publishing, a slug changed, a car
    // deleted): the fleet page, home, the model pages and the sitemaps are rebuilt (src/lib/edge/fleet-sig.ts)
    // (only with a tag store: pages served as built from the assets are never rebuilt)
    const self = env.WORKER_SELF_REFERENCE as { fetch(r: Request): Promise<Response> } | undefined;
    if (env.NEXT_TAG_CACHE_KV || env.NEXT_TAG_CACHE_D1) ctx.waitUntil((async () => {
      const [rows, seen, pending, deploySeen, warmed] = await Promise.all([fleetRows(env), readNumber(env, FLEET_SIG_KEY), readNumber(env, FLEET_SIG_CONFIRM_KEY), readNumber(env, DEPLOY_SEEN_KEY), readNumber(env, WARM_KEY)]);
      const sig = rows ? signatureOf(rows) : null;
      if (sig === null || seen === null) return;
      // after a change the pages are rebuilt twice, five minutes apart, so a page regenerated while the change was
      // being written cannot keep a stale list (the second pass is the confirm)
      const confirming = sig === seen && pending === sig;
      // the first tick after a deploy rebuilds them too: a page kept in the page cache by the previous build names that
      // build's style and script files, which are gone (the home page loaded without its styles on Oct 21)
      const deployed = deployNumber(deploymentOf(env));
      const newDeploy = deployed !== 0 && deploySeen !== deployed;
      let rebuiltForDeploy = !newDeploy;
      if (sig !== seen || confirming || newDeploy) {
        const r: Response = await handler.fetch(new Request(`${base.replace(/\/$/, '')}/api/jobs/public-rebuild`, { method: 'POST', headers: { ...auth, 'content-type': 'application/json' }, body: '{}' }), env, ctx);
        await r.text();
        if (r.ok) { await writeNumber(env, FLEET_SIG_KEY, sig); await writeNumber(env, FLEET_SIG_CONFIRM_KEY, confirming ? 0 : sig); if (newDeploy) { await writeNumber(env, DEPLOY_SEEN_KEY, deployed); rebuiltForDeploy = true; } }
      }
      // 0102: then the pages visitors open first are rendered once for this deploy (src/lib/edge/warm.ts): home, the fleet
      // page and each car page, through the service binding (each its own invocation), a few at a time within a budget;
      // the rest on the next ticks. Without it every car page was a cold render for its first visitor after a deploy.
      // 0106: an import's end asks for the same warm-up again (POST /api/jobs/warm-up, below).
      if (!rebuiltForDeploy || !self || deployed === 0 || warmed === null) return;
      await warmTick(env, rows!, deployed, warmed, self, base);
    })().catch(() => undefined));
    // the monthly statement emails (PDF first), once an hour: the first tick of each hour
    if (plan.minute < 5) run('/api/jobs/statements');
    // signed copies waiting (0077): through the Worker's own service binding, so each run is its own invocation
    const pdfJobs = new Request(`${base.replace(/\/$/, '')}/api/jobs/pdf`, { method: 'POST', headers: auth });
    if (due.pdf) ctx.waitUntil((self ? self.fetch(pdfJobs) : handler.fetch(pdfJobs, env, ctx)).then((r: Response) => r.text()).catch(() => undefined));
    // Turo emails waiting for their car, matched again after the fleet or what was learned changed (0088)
    if (due.turo) run('/api/jobs/turo-rematch');
    // confirmed bookings still without their rental agreement (0132): made and sent to sign
    if (due.agreements) run('/api/jobs/agreements');
    // the partner CRM links (0136): every 15 minutes and soon after a change, when the database says one is due
    if (due.crm) run('/api/jobs/partner-crm');
    // the deposit guard (0155): card holds captured before they lapse, money steps waiting for Stripe, balances followed up
    if (due.deposits) run('/api/jobs/deposits');
    // the retention purge of private files (0071), once an hour on the second tick
    if (plan.minute >= 5 && plan.minute < 10) run('/api/jobs/purge');
    // the usage guard (0080): Cloudflare's figures when the Worker has an analytics token, the alerts, once an hour on the third tick
    if (plan.minute >= 10 && plan.minute < 15) run('/api/jobs/usage');
  },

  async fetch(request: Request, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }): Promise<Response> {
    // r27b: http:// is answered with the https address before anything else (the scrapers of November 6 asked for every
    // page twice, over http and https, and both rendered)
    const secure = httpsRedirect(request.url);
    if (secure) return new Response(null, { status: request.method === 'GET' || request.method === 'HEAD' ? 301 : 308, headers: { location: secure, 'cache-control': 'public, max-age=86400', ...securityHeaders() } });
    const path = new URL(request.url).pathname;
    if (path.startsWith('/media/')) return media(request, env, path, ctx);
    // 2026-11-06: a build file the static assets do not have (a page from an older build than the 8 days the deploy keeps,
    // scripts/deploy/keep-assets.mjs) is a plain 404 here, never the app's HTML 404 page (a stylesheet or script answered
    // with HTML is what left the page half styled); the page's guard then reloads it once (src/lib/chunk-guard.ts)
    if (path.startsWith('/_next/static/')) return new Response('Not found', { status: 404, headers: { 'content-type': 'text/plain; charset=utf-8', 'cache-control': 'no-store', ...securityHeaders() } });
    // scanners asking for PHP, WordPress or dot files: answered before the app loads (a render costs a second of CPU
    // on a fresh isolate)
    if (isProbe(path) || unusedFrameworkPath(path)) return new Response('Not found', { status: 404, headers: { 'content-type': 'text/plain; charset=utf-8', 'cache-control': 'public, max-age=3600', ...securityHeaders() } });
    // 2026-10-30: SEO tools and scrapers, crawlers on the portals and on query-string views: answered here, before the
    // session refresh and the app (src/lib/edge/bot-shield.ts)
    // R23: the search scope flag is read (one KV read, kept 30 s) only for a crawler on a page outside the core crawl scope.
    // 0324: every crawler reaches every page (the owner's decision); while the month's crawler guard is on (CPU_GUARD_KEY,
    // the database's projected CPU cost above crawler_guard_usd), a crawler that is not a search or answer crawler is kept
    // to the crawl scope (bot-shield.ts keptToScope)
    // 2350: a place page outside our market: 404 here, kept a day by the caches, never a render (they were most of the
    // crawl and many answered 503).
    // 2402: any region that is off (release 40 keeps the place pages to Ontario), from the tick's mask; and a vehicle page of
    // a model year below the oldest one with pages (Program setting vpage_min_year). The tag store is read only for such an address.
    if (request.method === 'GET' || request.method === 'HEAD') {
      if (placeRegionBit(path) !== null && offMarketPlace(path, marketOf(await storedNumber(env, PLACE_MARKET_KEY)))) return outOfMarket(securityHeaders());
      if (vehiclePageYear(path) !== null && oldModelYear(path, await storedNumber(env, VPAGE_MIN_YEAR_KEY))) return oldYearGone(securityHeaders());
    }
    const ua0 = request.headers.get('user-agent');
    const core = await keptToScope(ua0, path, () => flag(env, SEARCH_SCOPE_KEY), () => flag(env, CPU_GUARD_KEY));
    const sh = shield(request.method, request.url, ua0, core);
    if (sh.kind !== 'pass') return shieldResponse(sh, securityHeaders());
    // r27b: Bytespider reads every page, paced (Cloudflare's rate limiting binding, per data centre); never refused outright
    if (ua0 && RATE_LIMITED_BOT.test(ua0)) {
      const rl = env.CRAWL_RL as { limit(o: { key: string }): Promise<{ success: boolean }> } | undefined;
      if (rl && !(await rl.limit({ key: 'bytespider' }).catch(() => ({ success: true }))).success) return tooMany(60, securityHeaders());
    }
    // r27b (the database swamped by scrapers, November 6): a long-tail page asked for from a hosting network, or by an agent
    // posing as a browser that keeps none of our cookies, gets its kept copy (up to a week old) or, without one, 429 (hosting
    // networks) or a tiny page that sets a cookie and reloads (people pass at once); never a render. Verified search and
    // AI crawlers and every agent that names itself always pass (src/lib/edge/scraper-guard.ts).
    const g = scraperGuard(request.method, path, (request as unknown as { cf?: Record<string, unknown> }).cf, ua0, request.headers.get('cookie'), request.headers.get('rsc') === '1');
    let guardCopy: Response | null = null;
    // cached-only mode (the database busy, tripped by the Worker itself below): long-tail pages from their kept copies only
    const tail = (request.method === 'GET' || request.method === 'HEAD') && longTail(path) && !hasSession(request.headers.get('cookie'));
    const serving = g === 'pass' && tail ? tailServing((await busyUntil(env)) > Date.now(), await flag(env, USAGE_CACHED_KEY), verifiedSearchEngine((request as unknown as { cf?: Record<string, unknown> }).cf)) : 'render';
    if (serving !== 'render') {
      const k = staleKey(request);
      guardCopy = k ? await crawlerCopy(k, request.headers.get('if-modified-since'), { cache: () => caches.open(EDGE_CACHE_NAME), env }, STALE_TTL_S) : null;
      if (!guardCopy && serving === 'copy-or-busy') return request.headers.get('rsc') === '1' ? tooMany(120, securityHeaders()) : busyPage();
    }
    if (g !== 'pass') {
      const k = staleKey(request);
      guardCopy = k ? await crawlerCopy(k, request.headers.get('if-modified-since'), { cache: () => caches.open(EDGE_CACHE_NAME), env }, STALE_TTL_S) : null;
      if (!guardCopy) return g === 'check' ? checkPage(securityHeaders()) : tooMany(3600, securityHeaders());
    }
    // 0324: R23's guard (every crawler, Google's too, 503 on the catalog from 70% of the included CPU time) is retired: the
    // crawler guard above keeps only the crawlers that are not search or answer crawlers to the crawl scope
    if (path === '/api/t' && request.method === 'POST') { const t = await track(request, env, ctx); if (t) return t; }
    if (path === '/api/jobs/warm-up' && request.method === 'POST') return warmUp(request, env, ctx);
    // r35: a write from another site stops here, for every route and server action (src/lib/security/request-guard.ts)
    if (crossSiteWriteRefused(request.method, request.url, request.headers.get('origin'), request.headers.get('sec-fetch-site'))) return crossSiteRefusal(securityHeaders());
    // An Admin viewing as someone is read only: every write outside the Admin portal stops here
    // (src/lib/security/view-as-guard.ts). Server actions are POSTs, so this covers all of them.
    if (viewAsWriteRefused(request.method, path, request.headers.get('cookie'))) return viewAsRefusal(request.headers.has('next-action'), securityHeaders());
    // The session is refreshed here, where the response can set the cookie, before a page reads it
    // (src/lib/auth/edge-refresh.ts: a page cannot store a refreshed session, and Supabase then ends it).
    let req = request;
    let setCookies: string[] = [];
    const sbUrl = env.NEXT_PUBLIC_SUPABASE_URL, sbKey = env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
    if (typeof sbUrl === 'string' && typeof sbKey === 'string' && !path.startsWith('/_next/static/')) {
      const r = await refreshSession(request, { url: sbUrl, anonKey: sbKey });
      if (r) { req = r.request; setCookies = r.setCookies; }
    }
    // The Admin portal is always the Admin themselves, even while viewing as someone elsewhere (src/server/view-as.ts).
    if (req.headers.has(ADMIN_AREA_HEADER) || isAdminArea(path)) {
      const h = new Headers(req.headers);
      h.delete(ADMIN_AREA_HEADER);
      if (isAdminArea(path)) h.set(ADMIN_AREA_HEADER, '1');
      req = new Request(req, { headers: h });
    }
    // The public pages the page cache answered before, from this data centre's copy, without loading the app
    // (src/lib/edge/page-cache.ts); what OpenNext answers from its page cache is kept for the next request.
    // 0106: the last good copy of each public page (no session) is kept too, for a week; when OpenNext answers 5xx or
    // takes more than 4 seconds (the database busy with an import or a load spike), the visitor gets that copy
    // (x-edge-stale) and the page is asked for again in the background; with no copy yet, the busy page that retries.
    const version = deploymentOf(env);
    const key = version ? edgeKey(req, version) : null;
    const sKey = version ? staleKey(req) : null;
    const origin = () => handler.fetch(new Request(req), env, ctx) as Promise<Response>;
    const crawler = isCrawler(request.headers.get('user-agent'));
    // r32: the place pages' global copy (src/lib/edge/global-store.ts): one copy for the whole network in R2, 30 days
    const bucket = env.NEXT_INC_CACHE_R2_BUCKET as R2Like | undefined;
    const gKey = bucket ? globalKey(req) : null;
    const gDeps = { bucket: bucket!, cache: () => caches.open(EDGE_CACHE_NAME), waitUntil: (p: Promise<unknown>) => ctx.waitUntil(p) };
    const global = gKey ? { match: () => globalMatch(gKey, { ...gDeps, crawler, ifModifiedSince: request.headers.get('if-modified-since') }), keep: (r: Response) => globalKeep(gKey, r, gDeps) } : undefined;
    const response: Response = guardCopy ? guardCopy : version && (key || sKey)
      ? await serveEdge(req, key, sKey, path, { cache: () => caches.open(EDGE_CACHE_NAME), env, version, origin, waitUntil: (p: Promise<unknown>) => ctx.waitUntil(p), global,
          // 0321: a crawler gets the page's last good copy (under 3 days old) or a 304, never a render when one is kept
          crawler: crawler ? { ifModifiedSince: request.headers.get('if-modified-since') } : undefined })
      : await origin();
    // r32: a write (a server action, a form, a webhook) may have queued an alert, a text or an urgent email: the send is
    // asked for at once instead of on the next cron tick (src/lib/edge/notify-kick.ts)
    if (request.method === 'POST' && response.status < 500) notifyKick(path, env, ctx, runJob(env, ctx));
    // a failed render of a long-tail page counts toward cached-only mode (BusyMeter: 5 within a minute in this isolate)
    if (tail && !guardCopy && renderFailed(response.status, response.headers.get(STALE_HEADER)) && busyMeter.failed(Date.now())) {
      busySeen = { at: Date.now(), until: Date.now() + BUSY_MS };
      ctx.waitUntil(writeNumber(env, BUSY_KEY, Date.now() + BUSY_MS).catch(() => undefined));
    }
    const type = response.headers.get('content-type') ?? '';
    const headers = new Headers(response.headers);
    for (const [k, v] of Object.entries(securityHeaders())) headers.set(k, v);
    // the partner widget (0136) is the one page other sites may frame
    const framed = embeddable(path);
    if (framed) headers.delete('X-Frame-Options');
    // the website's schema marker, read by the site check in the database (0063: waiting for the website deploy)
    headers.set(SCHEMA_HEADER, SCHEMA_MARKER);
    for (const c of setCookies) headers.append('set-cookie', c);
    // the email link's outbox row, kept through a sign-in redirect for the beacon (Live visitors, 0060)
    if (request.method === 'GET' && path.startsWith('/account/bookings/')) { const m = emailLinkCookie(request.url, true); if (m) headers.append('set-cookie', m); }
    if (!type.includes('text/html')) return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
    // where the visitor is browsing from (country-region, e.g. CA-ON), for the cookie notice (0075); not stored
    const geo = geoCode((request as Request & { cf?: { country?: string; regionCode?: string } }).cf);
    if (geo && !new RegExp(`(^|;\\s*)cc_geo=${geo}(;|$)`).test(request.headers.get('cookie') ?? '')) {
      headers.append('set-cookie', `cc_geo=${geo}; Path=/; Max-Age=86400; SameSite=Lax${new URL(request.url).protocol === 'https:' ? '; Secure' : ''}`);
    }
    // a page is never reused by the browser without asking first: OpenNext's stale-while-revalidate let Safari show a
    // page kept from a previous deploy, whose style files are gone (home loaded unstyled on phones, Oct 21). The
    // data centre's copy above is unaffected (it is kept before this line).
    // A signed-in page is the visitor's own: marked private, so no proxy between here and the browser keeps it.
    headers.set('cache-control', response.headers.get(STALE_HEADER) === 'busy' ? 'no-store' : hasSession(request.headers.get('cookie')) ? 'private, no-cache' : 'no-cache');
    const nonce = newNonce();
    headers.set('Content-Security-Policy', cspHeader(nonce, { turnstile: true, connectOrigins: supabaseOrigin(env.NEXT_PUBLIC_SUPABASE_URL), frameAncestors: framed ? 'https:' : undefined, voice: voicePage(path) }));
    const out = new Response(response.body, { status: response.status, statusText: response.statusText, headers });
    // @ts-expect-error: HTMLRewriter is a Workers global
    return new HTMLRewriter().on('script', new NonceAdder(nonce)).transform(out);
  }
};
// The browser calls Supabase for the public reads (src/lib/browser-rpc.ts). *.supabase.co is always allowed
// (csp.ts); a Supabase on the company's own address (infra/vps/CUTOVER.md) is added here.
function supabaseOrigin(url: unknown): string[] {
  try {
    const o = new URL(String(url)).origin;
    return o.endsWith('.supabase.co') ? [] : [o];
  } catch {
    return [];
  }
}

export default worker;

/** Cloudflare's country and region for a request, as CA-ON (or CA when the region is unknown); null when unknown. */
function geoCode(cf: { country?: string; regionCode?: string } | undefined): string | null {
  const c = (cf?.country ?? '').toUpperCase();
  if (!/^[A-Z]{2}$/.test(c) || c === 'XX' || c === 'T1') return null;
  const r = (cf?.regionCode ?? '').toUpperCase();
  return /^[A-Z0-9]{1,3}$/.test(r) ? `${c}-${r}` : c;
}

// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler } from './.open-next/worker.js';
